const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();

const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');

const userId = parseInt(match[1], 10);
return [{ json: { userId } }];

// Admins see company-wide numbers; everyone else only sees their own
// contacts/deals/tasks. ownerId is derived from the validated session
// (not a client-supplied param) so this can't be spoofed by editing the
// request query string.
const user = $input.first().json;

if (!user.id || !user.active) {
  throw new Error('Invalid session.');
}

const ownerId = user.role === 'admin' ? null : user.id;

// pipelineId is a client-supplied filter (which pipeline's dashboard to
// show) — unlike ownerId it's not a security scope, just a view filter,
// so it's safe to read straight from the query string.
const rawPipelineId = $('Webhook: get-dashboard').first().json.query?.pipeline_id;
const pipelineId = rawPipelineId ? parseInt(rawPipelineId, 10) : null;

return [{ json: { ownerId, role: user.role, pipelineId } }];
